mapper.select:
select f.file_id,f.file_name,f.file_path,f.file_type
from file f

    inner join file_project_relation fp on f.file_id = fp.file_id
    inner join project p  on  fp.project_id = p.project_id


    inner join file_node_relation fn on fn.file_id = f.file_id
    inner join mind_map mm on p.project_id = mm.project_id


    inner join project_dimension_relation pd on pd.project_id = pd.project_id
    inner join dimension d on pd.dimension_id = d.dimension_id


    inner join file_tag_relation fr on fr.file_id = f.file_id
    inner join tag t on t.tag_id = fr.tag_id

where 1=1

    and p.project_name = #{parms.projectName}


    and mm.node_name = #{parms.nodeName}


    and d.dimension_name = #{parms.dimension}


    and t.tag_name =  #{parms.tagName}


    and t.file_name =  #{parms.fileName}


    and t.file_type =  #{parms.fileType}

select f.file_type name ,count(1) value from file f
, file_project_relation fp where f.file_id = fp.file_id and fp.project_id = #{projectId}
group by file_type
